# Grid of the hyperparameters, with the length scale in minutes and the noise level as a standard deviation
ell_grid = 10**np.linspace(1.5, 3.4, 40)
noise_grid = 10**np.linspace(-2.5, np.log10(0.05), 16)

# Find the best length scale and noise level of one light curve on the grid
def fit_light_curve(t, lc):
    """Return the length scale and the noise level with the highest log marginal likelihood on the grid."""
    best_loglik = -np.inf
    for ell in ell_grid:
        for noise in noise_grid:
            loglik = log_marginal_likelihood(t, lc, ell, noise)
            if loglik > best_loglik:
                best_loglik, best_ell, best_noise = loglik, ell, noise
    return best_ell, best_noise
